func newTestDashboard(options Options) *Dashboard {
	options.Now = func() time.Time { return testNow }
	if options.Interval == 0 {
		options.Interval = 20 * time.Millisecond
	}
	return New(options)
}

func get(t *testing.T, handler http.Handler, path string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(http.MethodGet, path, nil)
	handler.ServeHTTP(recorder, request)
	return recorder

// New builds a dashboard over the given providers.
func New(options Options) *Dashboard {
	if options.Interval <= 0 {
		options.Interval = DefaultInterval
	}
	if options.MaxStreams <= 0 {
		options.MaxStreams = DefaultMaxStreams
	}
	if options.Now == nil {
		options.Now = time.Now
	}
	dashboard := &Dashboard{options: options, streams: make(chan struct{}, options.MaxStreams),
		decisions: newKeyedCache[decisionlog.Result](decisionCacheTTL, 64),
		rollouts:  newKeyedCache[[]insights.Rollout](decisionCacheTTL, 1),
		rollout:   newKeyedCache[insights.Rollout](decisionCacheTTL, 64),
		chains:    newKeyedCache[decisionlog.Chain](decisionCacheTTL, 64),
		summaries: newKeyedCache[insights.Summary](summaryCacheTTL, 8)}
	dashboard.clusters.TTL = clusterCacheTTL
	dashboard.SetSnapshots(options.Snapshots)
	dashboard.SetCluster(options.Cluster)
	if options.Journal != nil {
		dashboard.SetJournal(*options.Journal)
	}
	return dashboard
}

// SetJournal attaches the decision journal, history, insight, summary and
// region providers.
func (dashboard *Dashboard) SetJournal(journal Journal) {
	dashboard.journal.Store(&journal)
}

// SetSnapshots attaches this member's snapshot provider.
func (dashboard *Dashboard) SetSnapshots(source observability.SnapshotSource) {
	if source != nil {
		dashboard.snapshots.Store(&snapshotHolder{source: source})
	}
}

// SetCluster attaches the cell-wide provider.
func (dashboard *Dashboard) SetCluster(source observability.ClusterSource) {
	if source != nil {
		dashboard.cluster.Store(&clusterHolder{source: source})
	}
}

// Mount registers every page, its stream, the login form and the assets.
func (dashboard *Dashboard) Mount(mounter Mounter) {
	mounter.HandleStatic("GET /assets/{hash}/{file}", http.HandlerFunc(serveAsset))
	mounter.HandleLogin(dashboard.guard(http.HandlerFunc(dashboard.login)))
	for _, page := range slices.Concat(pages, detailPages) {
		mounter.Handle("GET "+page.path(), dashboard.guard(dashboard.pageHandler(page)))
		mounter.Handle("GET "+page.streamPath(), dashboard.guard(dashboard.streamHandler(page)))
	}
	mounter.Handle("POST /capacity/budget", dashboard.guard(http.HandlerFunc(dashboard.setBudget)))
}

// Handler returns the dashboard routes on their own mux without any
// authentication. Tests use it; production mounts on the private listener.
func (dashboard *Dashboard) Handler() http.Handler {
	mux := http.NewServeMux()
	dashboard.Mount(muxMounter{mux})
	return mux
}

type muxMounter struct{ mux *http.ServeMux }

func (mounter muxMounter) Handle(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleStatic(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleLogin(page http.Handler) { mounter.mux.Handle("GET /login", page) }

// contentSecurityPolicy allows only this listener's own files. Datastar
// evaluates its data-* expressions with Function, which needs unsafe-eval;
// there are no inline scripts and no inline style elements. ECharts writes
// its tooltip markup with style attributes, so style-src-attr alone allows
// inline style attributes; templ escapes every server value, so no request
// data can reach an attribute unescaped.
const contentSecurityPolicy = "default-src 'self'; script-src 'self' 'unsafe-eval'; style-src 'self'; " +
	"style-src-attr 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; " +
	"form-action 'self'; frame-ancestors 'none'"

// guard applies the browser hardening headers and the Host check.
func (dashboard *Dashboard) guard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if dashboard.options.RequireLiteralHost && !literalHost(request.Host) {
			http.Error(writer, "the dashboard must be addressed by IP or localhost", http.StatusMisdirectedRequest)
			return
		}
		header := writer.Header()
		header.Set("Content-Security-Policy", contentSecurityPolicy)
		header.Set("X-Content-Type-Options", "nosniff")
		header.Set("X-Frame-Options", "DENY")
		header.Set("Referrer-Policy", "same-origin")
		header.Set("Cache-Control", "no-store")
		next.ServeHTTP(writer, request)
	})
}

func literalHost(host string) bool { return observability.LiteralHost(host) }

// load gathers the view every page renders from. Missing providers and
// failing sections become notes on the view, never a failed request.
func (dashboard *Dashboard) load(ctx context.Context, page page, query url.Values, path map[string]string) view {
	current := view{Page: page, Now: dashboard.options.Now().UTC(), SignOut: dashboard.options.SignOut,
		Filter: parseEventFilter(query), State: parseState(query), Path: path}
	if region := path["r"]; region != "" {
		// A detail page whose path names its region shows that region.
		current.State.Region = region
	}
	if health := dashboard.options.Health; health != nil {
		current.Ready, current.Checks = health.Evaluate(ctx)
	}
	if holder := dashboard.snapshots.Load(); holder != nil {
		snapshot, err := holder.source.Snapshot(ctx, false)
		if err != nil {
			current.Notes = append(current.Notes, "This member's snapshot is unavailable.")
		} else {
			current.Local = &snapshot
		}
	} else {
		current.Notes = append(current.Notes, "This member is still starting; its providers are not attached yet.")
	}
	if holder := dashboard.cluster.Load(); holder != nil {
		snapshot, err := dashboard.clusters.Get(ctx, func(ctx context.Context) (observability.ClusterSnapshot, error) {
			return holder.source.Cluster(ctx, false)
		})
		if err != nil {
			current.Notes = append(current.Notes, "The cell-wide view is unavailable; showing this member only.")
		} else {
			current.Cluster = &snapshot
		}
	}
	if page.events > 0 && dashboard.options.Events != nil {
		current.Events = current.Filter.apply(dashboard.options.Events.Recent(0), page.events)
	}
	dashboard.loadJournal(ctx, &current)
	return current
}

func (dashboard *Dashboard) pageHandler(page page) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		path, found := page.pathValues(request)
		if !found {
			http.NotFound(writer, request)
			return
		}
		current := dashboard.load(request.Context(), page, request.URL.Query(), path)
		current.loadMetrics(request.Context())
		if page.slug == "region" && current.remote() {
			// The region page shows this member's region only; another one
			// has its own global view.
			http.Redirect(writer, request, "/regions/"+current.State.Region, http.StatusSeeOther)
			return
		}
		render(writer, request, layout(current))
	})
}

func (dashboard *Dashboard) login(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query()
	render(writer, request, login(query.Get("failed") == "1", observability.LocalRedirectPath(query.Get("next"))))
}

func render(writer http.ResponseWriter, request *http.Request, component templ.Component) {
	var body bytes.Buffer
	if err := component.Render(request.Context(), &body); err != nil {
		level := slog.LevelWarn
		if errors.Is(err, context.Canceled) {
			// The client went away; nothing is wrong with the dashboard.
			level = slog.LevelDebug
		}
		slog.Log(request.Context(), level, "dashboard render failed", observability.ComponentKey, "dashboard", "error", err)
		http.Error(writer, "render failed", http.StatusInternalServerError)
		return
	}
	writer.Header().Set("Content-Type", "text/html; charset=utf-8")
	writer.Header().Add("Vary", "Accept-Encoding")
	if !acceptsGzip(request.Header.Get("Accept-Encoding")) {
		_, _ = writer.Write(body.Bytes())
		return
	}
	writer.Header().Set("Content-Encoding", "gzip")
	zipped := gzip.NewWriter(writer)
	_, _ = zipped.Write(body.Bytes())
	_ = zipped.Close()
}

func (page page) path() string {
	if page.pattern != "" {
		return page.pattern
	}
	if page.slug == "" {
		return "/{$}"
	}
	return "/" + page.slug
}

func (page page) href() string { return "/" + page.slug }

// navSlug is the sidebar entry the page highlights.
func (page page) navSlug() string { return cmp.Or(page.parent, page.slug) }

func (page page) streamPath() string {
	if page.pattern != "" {
		return page.pattern + "/stream"
	}
	if page.slug == "" {
		return "/global/stream"
	}
	return "/" + page.slug + "/stream"
}

// pages is the sidebar, in order. The global multi-region view is the
// landing page.
var pages = []page{
	{slug: "", title: "Global", group: "Overview", needs: needGlobal | needInsights, body: overviewBody},
	{slug: "region", title: "Region", group: "Overview", events: 10, needs: needLocal | needInsights,
		decisions: regionDecisions, body: regionBody},
	{slug: "nodes", title: "Nodes", group: "Overview", needs: needGlobal, body: globalNodesBody},
	{slug: "volumes", title: "Volumes", group: "Overview", needs: needGlobal, body: globalVolumesBody},
	{slug: "insights", title: "Needs attention", group: "Overview",
		needs: needLocal | needInsights | needSummaries, body: insightsBody},
	{slug: "decisions", title: "Decisions", group: "Overview", needs: needLocal | needChain,
		decisions: journalDecisions, body: decisionsBody},
	{slug: "releases", title: "Releases", group: "Delivery", needs: needLocal | needVersions | needChain,
		decisions: releaseDecisions, body: releasesBody},
	{slug: "rollouts", title: "Rollouts", group: "Delivery", needs: needRollouts, decisions: rolloutDecisions,
		body: rolloutsBody},
	{slug: "ci", title: "Qualification", group: "Delivery", needs: needQualification,
		decisions: qualificationDecisions, body: ciBody},
	{slug: "topology", title: "Topology", group: "Infrastructure", needs: needLocal, body: topologyBody},
	{slug: "members", title: "Hosts", group: "Infrastructure", needs: needLocal, body: membersBody},
	{slug: "nats", title: "NATS", group: "Infrastructure", decisions: natsDecisions, body: natsBody},
	{slug: "terrabase", title: "TerraBase", group: "Infrastructure", needs: needLocal, decisions: terrabaseDecisions,
		body: terrabaseBody},
	{slug: "storage", title: "Storage", group: "Infrastructure", needs: needVolumes | needLocal, decisions: storageDecisions,
		body: storageBody},
	{slug: "capacity", title: "Capacity", group: "Infrastructure", needs: needCapacity, body: capacityBody},
	{slug: "cost", title: "OCI cost", group: "Infrastructure", needs: needLocal | needGlobal | needCapacity, body: costBody},
	{slug: "oci", title: "OCI", group: "Infrastructure", needs: needInventory, body: ociBody},
	{slug: "metric-catalog", title: "Metrics", group: "Logs", body: metricsBody},
	{slug: "events", title: "Events", group: "Logs", events: recentEvents, body: eventsBody},
}

func (dashboard *Dashboard) loadJournal(ctx context.Context, current *view) {
	holder := dashboard.journal.Load()
	if holder == nil {
		return
	}
	journal := *holder
	current.Journal = &journal
	needs := current.Page.needs
	if journal.Global != nil {
		current.Global = journal.Global.Regions()
	}
	if needs&needLocal != 0 && journal.Local != nil {
		summary := journal.Local(ctx)
		current.LocalSummary = &summary
	}
	if journal.Insights != nil {
		evaluation := journal.Insights.Current()
		current.Evaluation = &evaluation
	}
	if needs&needSummaries != 0 && journal.Summaries != nil {
		for _, window := range summaryWindows {
			summary, err := dashboard.summaries.get(ctx, window.String(), func(ctx context.Context) (insights.Summary, error) {
				return journal.Summaries.Summary(ctx, window)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "summary "+window.String())
				continue
			}
			current.Summaries = append(current.Summaries, summary)
		}
	}
	if current.Page.decisions != nil && journal.Decisions != nil {
		if query := current.Page.decisions(*current); query != nil {
			key, _ := json.Marshal(query)
			result, err := dashboard.decisions.get(ctx, string(key), func(ctx context.Context) (decisionlog.Result, error) {
				return journal.Decisions.Query(ctx, *query)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "decision journal")
			} else {
				current.Decisions = &result
			}
		}
	}
	id := current.State.param("id")
	if id == "" && current.Page.chain != nil {
		id = current.Page.chain(*current)
	}
	if needs&needChain != 0 && id != "" && journal.Decisions != nil {
		// Cached like the decision queries: a chain lookup may fan out to
		// every linked region, and every open stream re-renders each tick.
		chain, err := dashboard.chains.get(ctx, id, func(ctx context.Context) (decisionlog.Chain, error) {
			return journal.Decisions.Chain(ctx, id)
		})
		switch {
		case err == nil:
			current.Chain = &chain
		case !errors.Is(err, decisionlog.ErrNotFound):
			current.Unavailable = append(current.Unavailable, "decision chain")
		}
	}
	if needs&needVersions != 0 {
		current.loadVersions(ctx)
	}
	if needs&needCapacity != 0 && journal.Capacity != nil {
		current.loadCapacity(ctx, journal.Capacity)
	}
	if needs&needRollouts != 0 && journal.Rollouts != nil {
		if rollouts, err := dashboard.rollouts.get(ctx, "recent", journal.Rollouts.Rollouts); err != nil {
			current.Unavailable = append(current.Unavailable, "rollouts")
		} else {
			current.Rollouts = rollouts
		}
	}
	if needs&needRollout != 0 && journal.Rollouts != nil {
		rollout, err := dashboard.rollout.get(ctx, current.Path["id"], func(ctx context.Context) (insights.Rollout, error) {
			return journal.Rollouts.Rollout(ctx, current.Path["id"])
		})
		switch {
		case err == nil:
			current.Rollout = &rollout
		case !errors.Is(err, ErrRolloutNotFound):
			current.Unavailable = append(current.Unavailable, "rollouts")
		}
	}
	if needs&needVolumes != 0 && journal.Volumes != nil {
		if volumes, err := journal.Volumes.Volumes(ctx); err != nil {
			current.Unavailable = append(current.Unavailable, "volumes")
		} else {
			current.Volumes = volumes
		}
	}
	if needs&needQualification != 0 && journal.Qualification != nil {
		if runs, err := journal.Qualification.Qualifications(ctx); err != nil {
			current.Unavailable = append(current.Unavailable, "qualification")
		} else {
			current.Qualifications = runs
		}
	}
	if needs&needInventory != 0 && journal.Inventory != nil {
		observation, err := journal.Inventory.Inventory(ctx)
		current.Inventory, current.InventoryObservation = observation.Items, &observation
		if err != nil {
			current.Unavailable = append(current.Unavailable, "OCI inventory")
		}
	}
}

func (current *view) loadMetrics(ctx context.Context) {
	if current.Page.slug != "metric-catalog" || current.Journal == nil || current.Journal.Metrics == nil {
		return
	}
	catalog, err := current.Journal.Metrics.Catalog(ctx)
	if err != nil {
		current.Unavailable = append(current.Unavailable, "metric catalog")
		return
	}
	current.MetricCatalog = &catalog
	if metric := current.selectedMetric(); metric != nil {
		history, err := current.Journal.Metrics.History(ctx, observability.HistoryQuery{
			Metric: metric.Name, Start: current.Now.Add(-current.State.Range.Duration), End: current.Now,
			MaxSeries: 32,
		})
		if err != nil {
			current.Unavailable = append(current.Unavailable, "metric history")
			return
		}
		// Keep the newest observations without downsampling across gaps.
		limit := metricHistoryPointLimit / max(len(history.Series), 1)
		for index := range history.Series {
			points := history.Series[index].Points
			if len(points) > limit {
				history.Series[index].Points = points[len(points)-limit:]
				current.MetricHistoryLimited = true
			}
		}
		current.MetricHistory = &history
	}
}

