// lossyEvents keeps events in its ring but never delivers them live, as a
// bus whose full subscription dropped them.
type lossyEvents struct {
	mu     sync.Mutex
	events []observability.Event
}

func (source *lossyEvents) add(event observability.Event) {
	source.mu.Lock()
	defer source.mu.Unlock()
	event.Sequence = uint64(len(source.events) + 1)
	source.events = append([]observability.Event{event}, source.events...)
}

func (source *lossyEvents) Recent(int) []observability.Event {
	source.mu.Lock()
	defer source.mu.Unlock()
	return slices.Clone(source.events)
}

func (source *lossyEvents) Since(uint64, int) []observability.Event { return nil }

func (source *lossyEvents) Subscribe(ctx context.Context, _ int) <-chan observability.Event {
	channel := make(chan observability.Event)
	context.AfterFunc(ctx, func() { close(channel) })
	return channel
}

func NewEventBus(capacity int) *EventBus {
	if capacity <= 0 {
		capacity = DefaultEventCapacity
	}
	return &EventBus{ring: make([]Event, capacity), subscribers: map[*eventSubscriber]struct{}{}}
}

// initLocked gives a zero-value EventBus the default ring and subscriber set,
// so a bus that was declared rather than built with NewEventBus cannot divide
// by zero on the log path. bus.mu must be held.
func (bus *EventBus) initLocked() {
	if len(bus.ring) == 0 {
		bus.ring = make([]Event, DefaultEventCapacity)
	}
	if bus.subscribers == nil {
		bus.subscribers = map[*eventSubscriber]struct{}{}
	}
}

// Publish stores an event, assigning its sequence and a missing timestamp,
// and offers it to every subscriber. It returns the stored event.
func (bus *EventBus) Publish(event Event) Event {
	if bus == nil {
		return event
	}
	if event.Time.IsZero() {
		event.Time = time.Now().UTC()
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.sequence++
	event.Sequence = bus.sequence
	index := (bus.start + bus.size) % len(bus.ring)
	if bus.size == len(bus.ring) {
		bus.start = (bus.start + 1) % len(bus.ring)
	} else {
		bus.size++
	}
	bus.ring[index] = event
	for subscriber := range bus.subscribers {
		select {
		case subscriber.events <- event:
		default:
			bus.dropped.Add(1)
		}
	}
	bus.mu.Unlock()
	bus.published.Add(1)
	return event
}

// Recent returns up to limit of the newest events, oldest first. A
// non-positive limit returns the whole ring.
func (bus *EventBus) Recent(limit int) []Event {
	return bus.Since(0, limit)
}

// Since returns up to limit events with a sequence greater than after, oldest
// first, keeping the newest when more are available. A dashboard reconnecting
// with its last seen sequence uses it to resume without duplicates.
func (bus *EventBus) Since(after uint64, limit int) []Event {
	if bus == nil {
		return nil
	}
	bus.mu.Lock()
	defer bus.mu.Unlock()
	events := make([]Event, 0, bus.size)
	for offset := range bus.size {
		event := bus.ring[(bus.start+offset)%len(bus.ring)]
		if event.Sequence > after {
			events = append(events, event)
		}
	}
	if limit > 0 && len(events) > limit {
		events = events[len(events)-limit:]
	}
	return events
}

// Subscribe streams events published after the call until ctx ends, when the
// channel is closed. buffer bounds how far a subscriber may fall behind
// before it loses events.
func (bus *EventBus) Subscribe(ctx context.Context, buffer int) <-chan Event {
	if buffer <= 0 {
		buffer = 64
	}
	subscriber := &eventSubscriber{events: make(chan Event, buffer)}
	if bus == nil {
		close(subscriber.events)
		return subscriber.events
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.subscribers[subscriber] = struct{}{}
	bus.mu.Unlock()
	context.AfterFunc(ctx, func() {
		bus.mu.Lock()
		delete(bus.subscribers, subscriber)
		bus.mu.Unlock()
		close(subscriber.events)
	})
	return subscriber.events
}

func parseEventFilter(query url.Values) eventFilter {
	filter := eventFilter{}
	if level := strings.ToLower(query.Get("level")); slices.Contains(levelNames, level) {
		filter.Level = level
	}
	if component := query.Get("component"); validComponent(component) {
		filter.Component = component
	}
	if search := strings.TrimSpace(query.Get("q")); search != "" && validSearch(search) {
		filter.Search = strings.ToLower(search)
	}
	if at, err := time.Parse(time.RFC3339, query.Get("at")); err == nil {
		filter.At = at.UTC()
	}
	return filter
}

func eventContains(event observability.Event, lowerNeedle string) bool {
	if strings.Contains(strings.ToLower(event.Message), lowerNeedle) ||
		strings.Contains(strings.ToLower(event.Component), lowerNeedle) {
		return true
	}
	for key, value := range event.Attrs {
		if strings.Contains(strings.ToLower(key+"="+value), lowerNeedle) {
			return true
		}
	}
	return false
}

func validComponent(component string) bool {
	if component == "" || len(component) > 64 {
		return false
	}
	for _, char := range component {
		if !(char >= 'a' && char <= 'z' || char >= '0' && char <= '9' || strings.ContainsRune("._-", char)) {
			return false
		}
	}
	return true
}

func (filter eventFilter) matches(event observability.Event) bool {
	if filter.Component != "" && event.Component != filter.Component {
		return false
	}
	if !filter.At.IsZero() && (event.Time.Before(filter.At.Add(-eventWindow)) ||
		event.Time.After(filter.At.Add(eventWindow))) {
		return false
	}
	if filter.Search != "" && !eventContains(event, filter.Search) {
		return false
	}
	if filter.Level == "" {
		return true
	}
	var minimum, level slog.Level
	_ = minimum.UnmarshalText([]byte(filter.Level))
	if err := level.UnmarshalText([]byte(event.Level)); err != nil {
		return true
	}
	return level >= minimum
}

// apply returns at most limit matching events, newest first.
func (filter eventFilter) apply(events []observability.Event, limit int) []observability.Event {
	result := make([]observability.Event, 0, min(limit, len(events)))
	for index := len(events) - 1; index >= 0 && len(result) < limit; index-- {
		if filter.matches(events[index]) {
			result = append(result, events[index])
		}
	}
	return result
}

func (refresher *chromeRefresher) render(ctx context.Context) chromeRender {
	current := refresher.dashboard.load(ctx, refresher.page, refresher.query, nil)
	var body bytes.Buffer
	err := chrome(current).Render(ctx, &body)
	return chromeRender{state: current.State, html: body.String(), err: err}
}

// patch writes a rendered top bar when it changed since the last patch.
func (refresher *chromeRefresher) patch(sse *datastar.ServerSentEventGenerator, rendered chromeRender) error {
	if rendered.err != nil {
		return rendered.err
	}
	digest := fnv.New64a()
	_, _ = digest.Write([]byte(rendered.html))
	if sum := digest.Sum64(); sum != refresher.last {
		refresher.last = sum
		return sse.PatchElements(rendered.html)
	}
	return nil
}

func (dashboard *Dashboard) streamEvents(ctx context.Context, sse *datastar.ServerSentEventGenerator, page page,
	query url.Values,
) {
	filter := parseEventFilter(query)
	source := dashboard.options.Events
	ticker := time.NewTicker(dashboard.options.Interval)
	defer ticker.Stop()
	chromeState := &chromeRefresher{dashboard: dashboard, page: page, query: query}
	state := parseState(query)
	var err error
	var changes <-chan insights.Change
	subscribe := func() {
		if changes == nil {
			if journal := dashboard.journal.Load(); journal != nil && journal.Insights != nil {
				changes = journal.Insights.Subscribe(ctx, 16)
			}
		}
	}
	subscribe()
	// Subscribe before listing so nothing published in between is lost;
	// the sequence check drops what the listing already contains.
	live := source.Subscribe(ctx, 256)
	var seen uint64
	empty := false
	// shown are the sequences of the listed rows, newest first.
	var shown []uint64
	sequences := func(events []observability.Event) []uint64 {
		out := make([]uint64, 0, len(events))
		for _, event := range events {
			out = append(out, event.Sequence)
		}
		return out
	}
	reset := func() bool {
		events := filter.apply(source.Recent(0), page.events)
		if len(events) > 0 {
			seen = max(seen, events[0].Sequence)
		}
		empty = len(events) == 0
		shown = sequences(events)
		return sse.PatchElementTempl(eventRows(events, "events-rows")) == nil
	}
	if !reset() {
		return
	}
	first := chromeState.render(ctx)
	if err = chromeState.patch(sse, first); err != nil {
		return
	}
	state = first.state
	rendered := make(chan chromeRender, 1)
	rendering := false
	prepended := 0
	for {
		var batch []observability.Event
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			subscribe()
			if !rendering {
				rendering = true
				go func() { rendered <- chromeState.render(ctx) }()
			}
			// A matching event the bus dropped (full subscription) is
			// still in the ring: relist when the rows fell out of step.
			if !slices.Equal(sequences(filter.apply(source.Recent(0), page.events)), shown) {
				if !reset() {
					return
				}
				prepended = 0
			}
			continue
		case result := <-rendered:
			rendering = false
			if err = chromeState.patch(sse, result); err != nil {
				return
			}
			state = result.state
			continue
		case change, open := <-changes:
			if !open {
				changes = nil
				continue
			}
			if err := toast(ctx, sse, state, change); err != nil {
				return
			}
			continue
		case event, open := <-live:
			if !open {
				return
			}
			batch = append(batch, event)
		}
	drain:
		for len(batch) < eventBatch {
			select {
			case event, open := <-live:
				if !open {
					break drain
				}
				batch = append(batch, event)
			default:
				break drain
			}
		}
		// Rows are newest first: prepend the batch newest first as one patch.
		var fresh []observability.Event
		for index := len(batch) - 1; index >= 0; index-- {
			if batch[index].Sequence > seen && filter.matches(batch[index]) {
				fresh = append(fresh, batch[index])
			}
		}
		if len(fresh) == 0 {
			continue
		}
		seen = max(seen, fresh[0].Sequence)
		shown = slices.Concat(sequences(fresh), shown)
		shown = shown[:min(len(shown), page.events)]
		prepended += len(fresh)
		if prepended > page.events {
			if !reset() {
				return
			}
			prepended = 0
			continue
		}
		var rows bytes.Buffer
		for _, event := range fresh {
			if err := eventRow(event).Render(ctx, &rows); err != nil {
				return
			}
		}
		if err := sse.PatchElements(rows.String(), datastar.WithSelectorID("events-rows"),
			datastar.WithModePrepend()); err != nil {
			return
		}
		if empty {
			empty = false
			if err := sse.RemoveElementByID("events-rows-empty"); err != nil {
				return
			}
		}
	}
}

